TLM.f("Tempora/Epi5-0",{"officium":"Dominica V Post Epiphaniam","rule":["Gloria","Credo","Prefatio=Trinitate"],"sections":{"Introitus":[{"k":"ref","la":"Ps 96:7-8"},{"k":"text","la":"Adoráte Deum, omnes Angeli ejus: audívit, et lætáta est Sion: et exsultavérunt fíliæ Judæ."},{"k":"ref","la":"Ps 96:1"},{"k":"text","la":"Dóminus regnávit, exsúltet terra: læténtur ínsulæ multæ."},{"k":"macro","name":"Gloria"},{"k":"text","la":"Adoráte Deum, omnes Angeli ejus: audívit, et lætáta est Sion: et exsultavérunt fíliæ Judæ."}],"Oratio":[{"k":"text","la":"Famíliam tuam, quǽsumus, Dómine, contínua pietáte custódi: ut, quæ in sola spe grátiæ cœléstis innítitur, tua semper protectióne muniátur."},{"k":"macro","name":"Per Dominum"}],"Lectio":[{"k":"text","la":"Léctio Epístolæ beáti Pauli Apóstoli ad Colossénses"},{"k":"ref","la":"Col 3:12-17"},{"k":"text","la":"Fratres: Indúite vos sicut elécti Dei, sancti et dilécti, víscera misericórdiæ, benignitátem, humilitátem, modéstiam, patiéntiam: supportántes ínvicem, et donántes vobismetípsis, si quis advérsus áliquem habet querélam: sicut et Dóminus donávit vobis, ita et vos. Super ómnia autem hæc caritátem habéte, quod est vínculum perfectiónis: et pax Christi exsúltet in córdibus vestris, in qua et vocáti estis in uno córpore: et grati estóte. Verbum Christi hábitet in vobis abundánter, in omni sapiéntia, docéntes et commonéntes vosmetípsos psalmis, hymnis et cánticis spirituálibus, in grátia cantántes in córdibus vestris Deo. Omne, quodcúmque fácitis in verbo aut in ópere, ómnia in nómine Dómini Jesu Christi, grátias agéntes Deo et Patri per ipsum."}],"Graduale":[{"k":"ref","la":"Ps 101:16-17"},{"k":"text","la":"Timébunt gentes nomen tuum, Dómine, et omnes reges terræ glóriam tuam."},{"k":"text","la":"Quóniam ædificávit Dóminus Sion, et vidébitur in majestáte sua. Allelúja, allelúja.","mark":"V"},{"k":"ref","la":"Ps 96:1"},{"k":"text","la":"Dóminus regnávit, exsúltet terra: læténtur ínsulæ multæ. Allelúja.","mark":"V"}],"Evangelium":[{"k":"text","la":"Sequéntia ✠ sancti Evangélii secúndum Matthǽum"},{"k":"ref","la":"Matt 13:24-30"},{"k":"text","la":"In illo témpore: Dixit Jesus turbis parábolam hanc: Símile factum est regnum cœlórum hómini, qui seminávit bonum semen in agro suo. Cum autem dormírent hómines, venit inimícus ejus, et superseminávit zizánia in médio trítici, et ábiit. Cum autem crevísset herba et fructum fecísset, tunc apparuérunt et zizánia. Accedéntes autem servi patrisfamílias, dixérunt ei: Dómine, nonne bonum semen seminásti in agro tuo? Unde ergo habet zizánia? Et ait illis: Inimícus homo hoc fecit. Servi autem dixérunt ei: Vis, imus, et collígimus ea? Et ait: Non: ne forte colligéntes zizánia eradicétis simul cum eis et tríticum. Sínite utráque créscere usque ad messem, et in témpore messis dicam messóribus: Collígite primum zizánia, et alligáte ea in fascículos ad comburéndum, tríticum autem congregáte in hórreum meum."}],"Offertorium":[{"k":"ref","la":"Ps 117:16; 117:17"},{"k":"text","la":"Déxtera Dómini fecit virtutem, déxtera Dómini exaltávit me: non móriar, sed vivam, et narrábo ópera Dómini."}],"Secreta":[{"k":"text","la":"Hóstias tibi, Dómine, placatiónis offérimus: ut et delícta nostra miserátus absólvas, et nutántia corda tu dírigas."},{"k":"macro","name":"Per Dominum"}],"Communio":[{"k":"ref","la":"Luc 4:22"},{"k":"text","la":"Mirabántur omnes de his, quæ procedébant de ore Dei."}],"Postcommunio":[{"k":"text","la":"Quǽsumus, omnípotens Deus: ut illíus salutáris capiámus efféctum, cujus per hæc mystéria pignus accépimus."},{"k":"macro","name":"Per Dominum"}]},"hr":{"5e22ba60d4b44e32":{"t":"Ps 96, 7-8, Ps 96, 1\n(Ps 96, 7-8) Klanjajte se Bogu svi anđeli njegovi! Čuje Sion i raduje se, veselo pjevaju sve Judine kćeri. (Ps 96, 1) Gospodin kraljuje, neka kliče zemlja, neka se raduju mnogi otoci.\n<i>Slava Ocu, i Sinu, i Duhu Svetomu. Kako bijaše na početku, tako i sada i vazda i u vijeke vjekova. Amen</i>.\n(Ps 96, 7-8) Klanjajte se Bogu svi anđeli njegovi! Čuje Sion i raduje se, veselo pjevaju sve Judine kćeri."},"1f593f0de7c850c0":{"t":"<i>Pomolimo se</i>.\nČuvaj, molimo, Gospodine, svoju obitelj neprestano očinskom dobrotom, da ona, kojoj je jedina nada u nebeskoj milosti, uživa vazda tvoju zaštitu.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>."},"3a77ec4b1e9c3b41":{"t":"Kol 3, 12-17\nČitanje Poslanice bl. Pavla apostola Kološanima. Braćo: kao Božji odabranici, sveti i ljubljeni, budite od srca milosrdni, blagi, ponizni, čedni, strpljivi. Podnosite jedan drugoga i opraštajte jedan drugome, ako se tko ima potužiti na drugoga. Kao što je Gospodin vama oprostio, tako i vi opraštajte. Nadasve imajte ljubav koja je veza savršenstva. I Kristov mir, na koji ste pozvani, neka u vašim srcima vlada kao u jednom tijelu. – Budite i zahvalni! Kristova riječ neka obilno stanuje u vama, u svakoj mudrosti. Poučavajte i potičite jedan drugoga psalmima, himnima, duhovnim pjesmama, na poticaj milosti pjevajte Bogu u svojim srcima. Sve što god govorite i činite neka bude u ime Gospodina Isusa Krista zahvaljujući Bogu Ocu po njemu."},"30e75e455763b37f":{"t":"Ps 101, 16-17\nBojat će se narodi imena tvojega, Gospodine, i tvoje slave svi kraljevi zemlje. Jer je Gospodin sagradio Sion i objavit će se u svojem veličanstvu.\n\nPs 96, 1\n<i>Aleluja</i>, <i>aleluja</i>.\nGospodin kraljuje, neka kliče zemlja, neka se raduju mnogi otoci. <i>Aleluja</i>."},"790fad0541adc55a":{"t":"Mt 13, 24-30\nSlijedi sveto Evanđelje po Mateju. U ono vrijeme: Reče Isus narodu ovu usporedbu: Kraljevstvo je nebesko kao čovjek koji na svojoj njivi posije dobro sjeme. Ali kad su ljudi zaspali, dođe njegov neprijatelj, pa među pšenicu posije kukolj i otiđe. A kad usjev izraste i učini klas, pokaže se kukolj. I pristupe sluge domaćinu te mu rekoše: Gospodaru, zar nisi dobro sjeme posijao na svojoj njivi. Pa odakle kukolj? On im odgovori To je učinio neki neprijatelj. Sluge mu rekoše: Hoćeš li da odemo i da ga iščupamo? Odgovori: Ne, da ne biste čupajući kukolj iščupali zajedno i pšenicu. Pustite, nek' oboje raste do žetve! U vrijeme žetve reći ću žeteocima: Pokupite najprije kukolj i svežite ga u snopove da se spali, a pšenicu skupite u moju žitnicu."},"a63cb5f96fa870c3":{"t":"Ps 117, 16-17\nDesnica Gospodnja učini čudo, desnica me Gospodnja podiže! Neću umrijeti nego živjeti i naviještati djela Gospodnja."},"1c8e508485aa2b6d":{"t":"Prinosimo ti, Gospodine, pomirnu žrtvu da nam milosrdno oprostiš grijehe i da kolebljiva srca vodiš.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>."},"adad0f7f2fcbfa9b":{"t":"Uistinu je dostojno i pravedno, pravo i spasonosno, da vazda i svagdje zahvaljujemo tebi. Gospodine, sveti Oče, svemogući vječni Bože. – Ti si s jedinorođenim Sinom tvojim i s Duhom Svetim jedan Bog, jedan Gospodin, ne u jedinstvu jedne osobe, već u Trojstvu jedine biti. Što naime po tvojoj objavi vjerujemo o tvojoj slavi, to isto bez razlike i razlučivanja vjerujemo i o tvome Sinu i o Duhu Svetome. Tako se u ispovijedanju istinitog i vjekovječnog božanstva klanjamo i vlastitosti osoba i jedinstvu biti i jednakosti veličanstva. – Koje hvale anđeli i arkanđeli, kerubini i serafini koji ne prestaju svaki dan klicati govoreći složnim glasom:"},"d63bef8a01a22821":{"t":"Lk 4, 22\nSvi su se divili riječima koje su izlazile iz Božjih usta."},"6c7409b64a825e73":{"t":"<i>Pomolimo se</i>.\nMolimo, svemogući Bože, da postignemo ono spasenje, kojega smo zalog primili u ovim otajstvima.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>."}}});
